import{c as e,Q as s,j as a,m as o}from"./chunks/framework.W-g_WCNV.js";const k=JSON.parse('{"title":"Webhooks","description":"Send notifications to external services when events occur in GateKeeper.","frontmatter":{"title":"Webhooks","description":"Send notifications to external services when events occur in GateKeeper."},"headers":[],"relativePath":"admin/webhooks.md","filePath":"admin/webhooks.md"}'),i={name:"admin/webhooks.md"};function d(n,t,r,l,h,c){return s(),a("div",null,[...t[0]||(t[0]=[o(`<p>Webhooks let GateKeeper push notifications to Discord, Slack, Telegram, ntfy, a generic HTTP endpoint, or an email address whenever an auth or admin event occurs.</p><h2 id="adding-a-webhook" tabindex="-1">Adding a webhook <a class="header-anchor" href="#adding-a-webhook" aria-label="Permalink to &quot;Adding a webhook&quot;">​</a></h2><p>Go to <code>/webhooks</code> and click <strong>Add webhook</strong>. Choose a type, fill in the required fields, and optionally restrict which events it receives.</p><p>By default a webhook receives all events. To restrict it, check only the events you care about in the <strong>Events</strong> section of the dialog.</p><h2 id="webhook-types" tabindex="-1">Webhook types <a class="header-anchor" href="#webhook-types" aria-label="Permalink to &quot;Webhook types&quot;">​</a></h2><h3 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h3><p>Paste a Discord webhook URL. GateKeeper sends an embed with a colour-coded status (green for success, yellow for warning, red for failure).</p><p><strong>Required:</strong> Webhook URL from your Discord channel settings.</p><h3 id="slack" tabindex="-1">Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Slack&quot;">​</a></h3><p>Paste an incoming webhook URL from your Slack app configuration.</p><p><strong>Required:</strong> Webhook URL (starts with <code>https://hooks.slack.com/</code>).</p><h3 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h3><p>GateKeeper uses the Telegram Bot API to send messages to a chat or channel.</p><p><strong>Required:</strong></p><ul><li><strong>Bot token</strong> - from BotFather, format <code>123456:ABC...</code></li><li><strong>Chat ID</strong> - your chat or channel ID (use <code>@username</code> or a numeric ID like <code>-100123456789</code>)</li></ul><h3 id="ntfy-public" tabindex="-1">ntfy (public) <a class="header-anchor" href="#ntfy-public" aria-label="Permalink to &quot;ntfy (public)&quot;">​</a></h3><p>Posts to the public ntfy.sh service.</p><p><strong>Required:</strong> Topic name (e.g. <code>my-gatekeeper-alerts</code>). Messages go to <code>https://ntfy.sh/{topic}</code>.</p><h3 id="ntfy-self-hosted" tabindex="-1">ntfy (self-hosted) <a class="header-anchor" href="#ntfy-self-hosted" aria-label="Permalink to &quot;ntfy (self-hosted)&quot;">​</a></h3><p>Posts to your own ntfy instance with optional Basic authentication.</p><p><strong>Required:</strong></p><ul><li><strong>URL</strong> - base URL of your ntfy server (e.g. <code>https://ntfy.example.com</code>)</li><li><strong>Topic</strong> - topic name</li><li><strong>Username / Password</strong> - optional, only if your instance requires auth</li></ul><h3 id="generic-json" tabindex="-1">Generic JSON <a class="header-anchor" href="#generic-json" aria-label="Permalink to &quot;Generic JSON&quot;">​</a></h3><p>Posts a JSON object to any HTTP endpoint.</p><p><strong>Payload:</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;login.failure&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;user_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;abc123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ip&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.2.3.4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;detail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1716000000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gatekeeper&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Required:</strong> Webhook URL (must accept POST with <code>Content-Type: application/json</code>).</p><h3 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h3><p>Sends a plain-text email using the SMTP settings configured in <strong>Settings</strong>.</p><p><strong>Required:</strong> Recipient email address. SMTP must be configured first.</p><hr><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Event</th><th>Description</th></tr></thead><tbody><tr><td>Auth</td><td><code>login.success</code></td><td>User logged in with password</td></tr><tr><td>Auth</td><td><code>login.failure</code></td><td>Failed login attempt</td></tr><tr><td>Auth</td><td><code>login.passkey</code></td><td>User logged in with a passkey</td></tr><tr><td>Auth</td><td><code>otp.failed</code></td><td>Email OTP verification failed</td></tr><tr><td>Auth</td><td><code>totp.failed</code></td><td>Authenticator code failed</td></tr><tr><td>Auth</td><td><code>totp.recovery_used</code></td><td>Recovery code consumed</td></tr><tr><td>Account</td><td><code>password.changed</code></td><td>User changed their password</td></tr><tr><td>Account</td><td><code>totp.enrolled</code></td><td>Authenticator app set up</td></tr><tr><td>Account</td><td><code>totp.revoked</code></td><td>Authenticator app removed</td></tr><tr><td>Account</td><td><code>passkey.registered</code></td><td>New passkey added</td></tr><tr><td>Account</td><td><code>passkey.revoked</code></td><td>Passkey removed</td></tr><tr><td>Account</td><td><code>password.reset_requested</code></td><td>Reset link sent</td></tr><tr><td>Account</td><td><code>password.reset_completed</code></td><td>Password reset via link</td></tr><tr><td>Admin</td><td><code>user.created</code></td><td>New user account created</td></tr><tr><td>Admin</td><td><code>user.disabled</code></td><td>Account disabled</td></tr><tr><td>Admin</td><td><code>user.enabled</code></td><td>Account re-enabled</td></tr><tr><td>Admin</td><td><code>admin.password_set</code></td><td>Admin directly set a user password</td></tr><tr><td>Admin</td><td><code>session.revoked</code></td><td>Sessions terminated by admin</td></tr></tbody></table><hr><h2 id="testing-a-webhook" tabindex="-1">Testing a webhook <a class="header-anchor" href="#testing-a-webhook" aria-label="Permalink to &quot;Testing a webhook&quot;">​</a></h2><p>Click the arrow button on any webhook row to send a <code>test.ping</code> notification immediately. The page shows whether it succeeded or failed.</p><h2 id="enabling-and-disabling" tabindex="-1">Enabling and disabling <a class="header-anchor" href="#enabling-and-disabling" aria-label="Permalink to &quot;Enabling and disabling&quot;">​</a></h2><p>Click the toggle button on a webhook row to enable or disable it without deleting it. Disabled webhooks receive no notifications.</p>`,38)])])}const u=e(i,[["render",d]]);export{k as __pageData,u as default};
